CREATE DATABASE IF NOT EXISTS studytrack_final
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;
USE studytrack_final;
SET NAMES utf8mb4;

CREATE TABLE usuario (
    id_usuario INT NOT NULL AUTO_INCREMENT,
    nome_usuario VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL,
    senha VARCHAR(255) NOT NULL,
    PRIMARY KEY (id_usuario),
    CONSTRAINT uq_usuario_email UNIQUE (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE aluno (
    id_aluno INT NOT NULL AUTO_INCREMENT,
    id_usuario INT NOT NULL,
    matricula VARCHAR(30) NOT NULL,
    turma VARCHAR(30) NOT NULL,
    curso VARCHAR(100) NOT NULL,
    PRIMARY KEY (id_aluno),
    CONSTRAINT uq_aluno_usuario UNIQUE (id_usuario),
    CONSTRAINT uq_aluno_matricula UNIQUE (matricula),
    CONSTRAINT fk_aluno_usuario FOREIGN KEY (id_usuario)
        REFERENCES usuario(id_usuario)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE disciplina (
    id_disciplina INT NOT NULL AUTO_INCREMENT,
    nome_disciplina VARCHAR(100) NOT NULL,
    descricao_disciplina VARCHAR(500) NOT NULL,
    PRIMARY KEY (id_disciplina)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE material (
    id_material INT NOT NULL AUTO_INCREMENT,
    nome_material VARCHAR(150) NOT NULL,
    tipo VARCHAR(50) NOT NULL,
    descricao_material VARCHAR(1000) NOT NULL,
    link VARCHAR(500) NULL,
    categoria VARCHAR(80) NULL,
    autor VARCHAR(150) NULL,
    PRIMARY KEY (id_material)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE plano_estudo (
    id_plano INT NOT NULL AUTO_INCREMENT,
    id_aluno INT NOT NULL,
    nome_plano VARCHAR(120) NOT NULL,
    objetivo VARCHAR(255) NOT NULL,
    descricao VARCHAR(500) NULL,
    data_inicio DATE NOT NULL,
    data_fim DATE NULL,
    status_plano VARCHAR(20) NOT NULL DEFAULT 'ativo',
    PRIMARY KEY (id_plano),
    CONSTRAINT chk_plano_datas
        CHECK (data_fim IS NULL OR data_fim >= data_inicio),
    CONSTRAINT chk_plano_status
        CHECK (status_plano IN ('planejado', 'ativo', 'pausado', 'concluido', 'cancelado')),
    CONSTRAINT fk_plano_aluno FOREIGN KEY (id_aluno)
        REFERENCES aluno(id_aluno)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE atividade (
    id_atividade INT NOT NULL AUTO_INCREMENT,
    id_plano INT NOT NULL,
    id_disciplina INT NOT NULL,
    titulo VARCHAR(150) NOT NULL,
    descricao VARCHAR(500) NULL,
    prazo DATE NULL,
    prioridade VARCHAR(20) NOT NULL DEFAULT 'media',
    status VARCHAR(30) NOT NULL DEFAULT 'pendente',
    criada_em DATETIME NOT NULL,
    concluida_em DATETIME NULL,
    PRIMARY KEY (id_atividade),
    CONSTRAINT chk_atividade_prioridade
        CHECK (prioridade IN ('baixa', 'media', 'alta')),
    CONSTRAINT chk_atividade_status
        CHECK (status IN ('pendente', 'em andamento', 'concluida', 'cancelada')),
    CONSTRAINT chk_atividade_datas
        CHECK (concluida_em IS NULL OR concluida_em >= criada_em),
    CONSTRAINT chk_atividade_conclusao
        CHECK ((status = 'concluida' AND concluida_em IS NOT NULL)
            OR (status <> 'concluida' AND concluida_em IS NULL)),
    CONSTRAINT fk_atividade_plano FOREIGN KEY (id_plano)
        REFERENCES plano_estudo(id_plano)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_atividade_disciplina FOREIGN KEY (id_disciplina)
        REFERENCES disciplina(id_disciplina)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE atividade_material (
    id_atividade INT NOT NULL,
    id_material INT NOT NULL,
    PRIMARY KEY (id_atividade, id_material),
    CONSTRAINT fk_am_atividade FOREIGN KEY (id_atividade)
        REFERENCES atividade(id_atividade)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_am_material FOREIGN KEY (id_material)
        REFERENCES material(id_material)
        ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE historico_atividade (
    id_historico INT NOT NULL AUTO_INCREMENT,
    id_atividade INT NOT NULL,
    data_hora DATETIME NOT NULL,
    tipo_evento VARCHAR(30) NOT NULL,
    status_anterior VARCHAR(30) NULL,
    status_novo VARCHAR(30) NOT NULL,
    descricao VARCHAR(300) NOT NULL,
    PRIMARY KEY (id_historico),
    CONSTRAINT chk_historico_status_anterior
        CHECK (status_anterior IS NULL OR status_anterior IN ('pendente', 'em andamento', 'concluida', 'cancelada')),
    CONSTRAINT chk_historico_status_novo
        CHECK (status_novo IN ('pendente', 'em andamento', 'concluida', 'cancelada')),
    CONSTRAINT fk_historico_atividade FOREIGN KEY (id_atividade)
        REFERENCES atividade(id_atividade)
        ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;











































