INSERT INTO plano_estudo (id_plano, id_aluno, nome_plano, objetivo, descricao, data_inicio, data_fim, status_plano) VALUES
    (1, 1, 'Plano de estudos 001', 'Organizar e acompanhar os estudos da semana', 'A rotina prioriza Matemática e Sociologia, com leitura dos materiais, resolução de exercícios e revisão ao final de cada sessão. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-01-01', NULL, 'ativo'),
    (2, 2, 'Plano de estudos 002', 'Organizar e acompanhar os estudos da semana', 'O cronograma reserva momentos para retomar Português e avançar em Filosofia, registrando dúvidas para a próxima revisão. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-01-01', NULL, 'ativo'),
    (3, 3, 'Plano de estudos 003', 'Organizar e acompanhar os estudos da semana', 'As atividades foram distribuídas em etapas para estudar Programação e Redes, acompanhar os prazos e consolidar os pontos principais. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-01-01', '2026-06-07', 'concluido'),
    (4, 4, 'Plano de estudos 004', 'Organizar e acompanhar os estudos da semana', 'A proposta é manter uma sequência regular de estudos em Banco de Dados e Desenvolvimento Web, alternando conteúdo teórico e prática. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-01-05', NULL, 'ativo'),
    (5, 5, 'Plano de estudos 005', 'Organizar e acompanhar os estudos da semana', 'A organização semanal combina leitura, anotações e exercícios de História e Estatística, com atenção às tarefas próximas do prazo. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-01-05', NULL, 'ativo'),
    (6, 6, 'Plano de estudos 006', 'Organizar e acompanhar os estudos da semana', 'Este ciclo reúne atividades de Geografia e Literatura; ao concluir cada etapa, o estudante revisa os erros e atualiza seu progresso. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-01-05', '2026-06-10', 'concluido'),
    (7, 7, 'Plano de estudos 007', 'Organizar e acompanhar os estudos da semana', 'O plano busca revisar os conceitos centrais de Biologia e aplicar o conteúdo em exercícios de Educação Física, sem acumular tarefas. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-01-05', NULL, 'ativo'),
    (8, 8, 'Plano de estudos 008', 'Organizar e acompanhar os estudos da semana', 'O estudo de Física e Empreendedorismo foi dividido em períodos curtos, com pausas para conferir o entendimento e reorganizar prioridades. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-01-09', NULL, 'ativo'),
    (9, 9, 'Plano de estudos 009', 'Organizar e acompanhar os estudos da semana', 'O acompanhamento concentra-se nos conteúdos de Química e Segurança da Informação, com metas de leitura, prática e revisão das anotações. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-01-09', '2026-06-13', 'concluido'),
    (10, 10, 'Plano de estudos 010', 'Organizar e acompanhar os estudos da semana', 'A sequência integra teoria e exercícios de Inglês e Arquitetura de Computadores, mantendo os prazos visíveis durante a semana. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-01-09', NULL, 'ativo'),
    (11, 11, 'Plano de estudos 011', 'Organizar e acompanhar os estudos da semana', 'As sessões alternam a retomada dos fundamentos de Sociologia e a prática de Matemática, para acompanhar o avanço de cada conteúdo. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-01-09', NULL, 'ativo'),
    (12, 12, 'Plano de estudos 012', 'Organizar e acompanhar os estudos da semana', 'O estudante utilizará os materiais de Filosofia e Português para preparar resumos, resolver questões e revisar os pontos de maior dificuldade. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-01-13', NULL, 'ativo'),
    (13, 13, 'Plano de estudos 013', 'Organizar e acompanhar os estudos da semana', 'A rotina prioriza Redes e Programação, com leitura dos materiais, resolução de exercícios e revisão ao final de cada sessão. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-01-13', NULL, 'ativo'),
    (14, 14, 'Plano de estudos 014', 'Organizar e acompanhar os estudos da semana', 'O cronograma reserva momentos para retomar Desenvolvimento Web e avançar em Banco de Dados, registrando dúvidas para a próxima revisão. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-01-13', NULL, 'ativo'),
    (15, 15, 'Plano de estudos 015', 'Organizar e acompanhar os estudos da semana', 'As atividades foram distribuídas em etapas para estudar Estatística e História, acompanhar os prazos e consolidar os pontos principais. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-01-13', '2026-06-19', 'concluido'),
    (16, 16, 'Plano de estudos 016', 'Organizar e acompanhar os estudos da semana', 'A proposta é manter uma sequência regular de estudos em Literatura e Geografia, alternando conteúdo teórico e prática. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-01-17', NULL, 'ativo'),
    (17, 17, 'Plano de estudos 017', 'Organizar e acompanhar os estudos da semana', 'A organização semanal combina leitura, anotações e exercícios de Educação Física e Biologia, com atenção às tarefas próximas do prazo. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-01-17', NULL, 'ativo'),
    (18, 18, 'Plano de estudos 018', 'Organizar e acompanhar os estudos da semana', 'Este ciclo reúne atividades de Empreendedorismo e Física; ao concluir cada etapa, o estudante revisa os erros e atualiza seu progresso. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-01-17', '2026-06-22', 'concluido'),
    (19, 19, 'Plano de estudos 019', 'Organizar e acompanhar os estudos da semana', 'O plano busca revisar os conceitos centrais de Segurança da Informação e aplicar o conteúdo em exercícios de Química, sem acumular tarefas. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-01-17', NULL, 'ativo'),
    (20, 20, 'Plano de estudos 020', 'Organizar e acompanhar os estudos da semana', 'O estudo de Arquitetura de Computadores e Inglês foi dividido em períodos curtos, com pausas para conferir o entendimento e reorganizar prioridades. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-01-21', NULL, 'ativo'),
    (21, 21, 'Plano de estudos 021', 'Organizar e acompanhar os estudos da semana', 'O acompanhamento concentra-se nos conteúdos de Matemática e Sociologia, com metas de leitura, prática e revisão das anotações. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-01-21', '2026-06-25', 'concluido'),
    (22, 22, 'Plano de estudos 022', 'Organizar e acompanhar os estudos da semana', 'A sequência integra teoria e exercícios de Português e Filosofia, mantendo os prazos visíveis durante a semana. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-01-21', NULL, 'ativo'),
    (23, 23, 'Plano de estudos 023', 'Organizar e acompanhar os estudos da semana', 'As sessões alternam a retomada dos fundamentos de Programação e a prática de Redes, para acompanhar o avanço de cada conteúdo. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-01-21', NULL, 'ativo'),
    (24, 24, 'Plano de estudos 024', 'Organizar e acompanhar os estudos da semana', 'O estudante utilizará os materiais de Banco de Dados e Desenvolvimento Web para preparar resumos, resolver questões e revisar os pontos de maior dificuldade. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-01-25', NULL, 'ativo'),
    (25, 25, 'Plano de estudos 025', 'Organizar e acompanhar os estudos da semana', 'A rotina prioriza História e Estatística, com leitura dos materiais, resolução de exercícios e revisão ao final de cada sessão. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-01-25', NULL, 'ativo'),
