    (283, 33, 'Plano de estudos 283 - Revisao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'O plano busca revisar os conceitos centrais de Literatura e aplicar o conteúdo em exercícios de Programação, sem acumular tarefas. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-07-10', NULL, 'pausado'),
    (284, 34, 'Plano de estudos 284 - Consolidacao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'O estudo de Inglês e Educação Física foi dividido em períodos curtos, com pausas para conferir o entendimento e reorganizar prioridades. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-07-12', NULL, 'pausado'),
    (285, 35, 'Plano de estudos 285 - Revisao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'O acompanhamento concentra-se nos conteúdos de Banco de Dados e Sociologia, com metas de leitura, prática e revisão das anotações. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-07-14', NULL, 'pausado'),
    (286, 36, 'Plano de estudos 286 - Consolidacao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'A sequência integra teoria e exercícios de Empreendedorismo e História, mantendo os prazos visíveis durante a semana. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-06-01', NULL, 'pausado'),
    (287, 37, 'Plano de estudos 287 - Revisao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'As sessões alternam a retomada dos fundamentos de Filosofia e a prática de Segurança da Informação, para acompanhar o avanço de cada conteúdo. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-06-03', NULL, 'pausado'),
    (288, 38, 'Plano de estudos 288 - Consolidacao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'O estudante utilizará os materiais de Geografia e Redes para preparar resumos, resolver questões e revisar os pontos de maior dificuldade. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-06-05', NULL, 'pausado'),
    (289, 39, 'Plano de estudos 289 - Revisao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'A rotina prioriza Arquitetura de Computadores e Biologia, com leitura dos materiais, resolução de exercícios e revisão ao final de cada sessão. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-06-07', NULL, 'pausado'),
    (290, 40, 'Plano de estudos 290 - Consolidacao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'O cronograma reserva momentos para retomar Desenvolvimento Web e avançar em Matemática, registrando dúvidas para a próxima revisão. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-06-09', NULL, 'pausado'),
    (291, 41, 'Plano de estudos 291 - Revisao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'As atividades foram distribuídas em etapas para estudar Física e Estatística, acompanhar os prazos e consolidar os pontos principais. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-06-11', NULL, 'pausado'),
    (292, 42, 'Plano de estudos 292 - Consolidacao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'A proposta é manter uma sequência regular de estudos em Português e Química, alternando conteúdo teórico e prática. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-06-13', NULL, 'pausado'),
    (293, 43, 'Plano de estudos 293 - Revisao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'A organização semanal combina leitura, anotações e exercícios de Literatura e Programação, com atenção às tarefas próximas do prazo. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-06-15', NULL, 'pausado'),
    (294, 44, 'Plano de estudos 294 - Consolidacao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'Este ciclo reúne atividades de Inglês e Educação Física; ao concluir cada etapa, o estudante revisa os erros e atualiza seu progresso. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-06-17', NULL, 'pausado'),
    (295, 45, 'Plano de estudos 295 - Revisao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'O plano busca revisar os conceitos centrais de Banco de Dados e aplicar o conteúdo em exercícios de Sociologia, sem acumular tarefas. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-06-19', NULL, 'pausado'),
    (296, 46, 'Plano de estudos 296 - Consolidacao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'O estudo de Empreendedorismo e História foi dividido em períodos curtos, com pausas para conferir o entendimento e reorganizar prioridades. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-06-21', NULL, 'pausado'),
    (297, 47, 'Plano de estudos 297 - Revisao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'O acompanhamento concentra-se nos conteúdos de Filosofia e Segurança da Informação, com metas de leitura, prática e revisão das anotações. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-06-23', NULL, 'pausado'),
    (298, 48, 'Plano de estudos 298 - Consolidacao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'A sequência integra teoria e exercícios de Geografia e Redes, mantendo os prazos visíveis durante a semana. Os exercícios práticos e os procedimentos utilizados serão registrados para facilitar a consulta posterior.', '2026-06-25', NULL, 'pausado'),
    (299, 49, 'Plano de estudos 299 - Revisao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'As sessões alternam a retomada dos fundamentos de Arquitetura de Computadores e a prática de Biologia, para acompanhar o avanço de cada conteúdo. As revisões relacionarão os conceitos estudados a exemplos de planejamento e organização.', '2026-06-27', NULL, 'pausado'),
    (300, 50, 'Plano de estudos 300 - Consolidacao', 'Organizar atividades, acompanhar prazos e consolidar os conteudos estudados.', 'O estudante utilizará os materiais de Desenvolvimento Web e Matemática para preparar resumos, resolver questões e revisar os pontos de maior dificuldade. As anotações destacarão conceitos técnicos, componentes e relações entre os tópicos estudados.', '2026-06-29', NULL, 'pausado');
